-- =================================================================
--  INFOBOARD → HOFER TOOL, Schritt 2a: die Daten selbst
--
--  Legt die Zwischentabelle ib_import an und füllt sie mit allen
--  2593 Balken aus infoBoard (Stand 28.09.2026, ab 2022, nur
--  Maschinenzeilen). Danach infoboard-import.sql ausführen.
--
--  Läuft gefahrlos mehrfach: die Tabelle wird vorher geleert.
-- =================================================================

drop table if exists ib_import;
create table ib_import (
  ib_idx text, balken_text text, start_zeit text, end_zeit text,
  soll_menge text, ist_menge text, prozent text, farbe text, zeichen text,
  prioritaet text, geaendert text, geaendert_von text,
  maschine text, maschine_idx text, ib_guid text
);




















select count(*) as balken_geladen from ib_import;
